), updated as (
  update private.learning_content c
  set provenance = u.item->'provenance',
      payload = case when pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(c.payload->>'review_note', 'UTF8')), 'hex') = u.item->>'previous_review_note_sha256'
        then pg_catalog.jsonb_set(c.payload, '{review_note}', u.item->'review_note') else c.payload end,
      revision = c.revision + 1
  from updates u
  where c.id = (u.item->>'id')::uuid and c.scope = 'platform'
    and c.provenance->'record'->>'provenance_id' = u.item->>'previous_provenance_id'
  returning c.*
)
insert into private.learning_history(content_id,scope_key,revision,action,changed_by,snapshot)
select id,'platform',revision,'public_provenance',null,payload || (to_jsonb(updated)-'payload') from updated;

update private.reference_ulp_limitation_periods
